-- Datos MOCK/DEMO para desarrollo local. Generado por
-- supabase/seed/generate_seed.py -- no ejecutar contra producción.
-- Ningún nombre, reseña o precio corresponde a un lugar real.

begin;

-- ============================================================================
-- SALVAGUARDA: este archivo carga datos FICTICIOS (MOCK) de desarrollo.
-- NUNCA debe correr contra un proyecto con usuarios o datos reales.
--
-- Para confirmar que sabés lo que estás haciendo, corré esta línea ANTES
-- de este archivo, en la MISMA sesión/conexión (psql, Supabase SQL Editor, etc.):
--
--   SET myapp.confirm_mock_seed = 'si-quiero-cargar-datos-ficticios';
--
-- Sin esa confirmación explícita, si la base ya tiene algún lugar real
-- (is_mock = false), o si ya tiene algún perfil que no sea uno de los
-- usuarios de desarrollo de este seed, este script se detiene sin cambiar nada.
-- ============================================================================
do $$
begin
  if coalesce(current_setting('myapp.confirm_mock_seed', true), '') <> 'si-quiero-cargar-datos-ficticios' then
    raise exception 'Seed MOCK abortado: falta confirmación explícita. Corré antes: SET myapp.confirm_mock_seed = ''si-quiero-cargar-datos-ficticios''; -- Este seed es SOLO para desarrollo local, nunca para producción.';
  end if;

  if exists (select 1 from public.places where is_mock = false) then
    raise exception 'Seed MOCK abortado: ya existen lugares reales (is_mock = false) en esta base. No se puede sembrar datos ficticios sobre datos reales.';
  end if;

  if exists (select 1 from public.profiles where id not in ('11111111-1111-1111-1111-111111111101', '11111111-1111-1111-1111-111111111102', '11111111-1111-1111-1111-111111111103', '11111111-1111-1111-1111-111111111104', '11111111-1111-1111-1111-111111111105', '11111111-1111-1111-1111-111111111106')) then
    raise exception 'Seed MOCK abortado: ya existen perfiles que no son los usuarios de desarrollo de este seed -- esta base ya tiene cuentas reales, aunque todavía no tenga lugares reales. No se puede sembrar datos ficticios ahí.';
  end if;
end
$$;



-- El trigger on_auth_user_created ya inserta el profile correspondiente.

with inserted_places as (
  returning id, name
)
select id, 'https://picsum.photos/seed/' || md5(id::text) || '/800/600', 0
from inserted_places;

with target_places as (
  select id from public.places where is_mock = true order by created_at limit 40
)
select p.id, u.id, r.rating, r.comment, r.amount_paid, r.occasion
from target_places p
cross join lateral (
  select * from (values
    ('11111111-1111-1111-1111-111111111101'::uuid, 5, 'Un poco caro para lo que ofrece, pero se disfruta.', 49687, 'amigos'),
    ('11111111-1111-1111-1111-111111111102'::uuid, 3, 'Un poco caro para lo que ofrece, pero se disfruta.', 37782, 'trabajo'),
    ('11111111-1111-1111-1111-111111111103'::uuid, 3, 'Ideal para ir en grupo, precios justos.', 15350, 'solo'),
    ('11111111-1111-1111-1111-111111111104'::uuid, 4, 'Excelente para desconectarse un rato.', 76592, 'familia'),
    ('11111111-1111-1111-1111-111111111105'::uuid, 3, 'Un poco caro para lo que ofrece, pero se disfruta.', 52762, 'familia'),
    ('11111111-1111-1111-1111-111111111106'::uuid, 5, 'Relación precio/calidad muy buena.', 24329, 'pareja')
  ) as v(user_id, rating, comment, amount_paid, occasion)
  order by random()
  limit 3
) as r(user_id, rating, comment, amount_paid, occasion)
join auth.users u on u.id = r.user_id
on conflict (place_id, user_id) do nothing;

commit;

